'use strict';
const SpendingUI=(()=>{
 const number=n=>(Number(n)||0).toLocaleString('th-TH',{maximumFractionDigits:2});
 function refresh(message){const position=$('#modal').scrollTop;save();clock.reset();render();open();$('#modal').scrollTop=position;if(message)toast(message)}
 function open(){const s=state,report=LifeSpending.summary(s),age=Engine.biological(s),locked=!LifeSpending.allowed(s),investLocked=locked||age<18,def=LifeSpending.strategies.find(p=>p.id===report.strategy);modal(`<section class="spending-dialog"><span class="eyebrow">ใช้เงิน · วางแผนอนาคต</span><h2>เงินพร้อมใช้ ${number(report.cash)} ทอง</h2><div class="wallet-summary"><div><small>เงินลงทุน</small><b>${number(report.invested)}</b></div><div><small>บ้านของตัวเอง</small><b>${report.owned?'มีแล้ว':'ยังไม่มี'}</b></div><div><small>ทรัพย์สินส่วนตัวรวม</small><b>${number(report.netWorth)}</b></div></div><p class="spending-note">รายได้ล่าสุด ${number(report.income)} · ค่าครองชีพ ${number(report.householdCost)} ทอง</p>${locked?'<p class="spending-warning">อ่านผลหรือตัดสินใจเรื่องที่ค้างอยู่ก่อนใช้เงิน</p>':''}<button class="secondary" id="openEconomyFromSpend">บัญชีรายรับ หนี้ และแผนค่าครองชีพ →</button><p class="spending-note">1 ทอง = 1 USD · ราคาค่าครองชีพจำลองจากระดับอเมริกา</p><h3>วันนี้อยากใช้เงินกับอะไร?</h3><div class="spending-options">${LifeSpending.options(s).map(p=>`<button class="spending-option" data-spend="${p.id}" ${p.available?'':'disabled'}><span><b>${esc(p.name)}</b><small>${esc(p.hint)}</small>${!p.available?`<em>${esc(p.reason)}</em>`:''}</span><strong>${p.cost}<small>ทอง</small></strong></button>`).join('')}</div><p class="spending-note">แต่ละรายการซื้อได้หนึ่งครั้งต่อปีชีวิต ของใช้และสัตว์เลี้ยงเลือกเพิ่มได้จากร้าน</p><div class="spending-links"><button class="secondary" id="spendShop">ของใช้และงานอดิเรก →</button><button class="secondary" id="spendPets">สัตว์เลี้ยง →</button></div><h3>เงินเก็บและการลงทุน</h3>${age<18?'<p class="spending-note">บัญชีลงทุนจะเปิดเมื่อถึงวัยผู้ใหญ่ของเผ่าคุณ</p>':''}<div class="saving-strategies">${LifeSpending.strategies.map(p=>`<button class="saving-strategy ${p.id===report.strategy?'selected':''}" data-saving-strategy="${p.id}" aria-pressed="${p.id===report.strategy}" ${investLocked?'disabled':''}><b>${p.name}</b><small>${p.description}</small></button>`).join('')}</div><p class="spending-note">เลือกไว้: ${esc(def.name)} · เงินพร้อมใช้แยกจากเงินลงทุน กำไรและขาดทุนเกิดเมื่อเวลาเดินต่อ</p><form id="investmentForm" class="investment-form"><label>จำนวนทอง<input id="investmentAmount" type="number" min="0.01" max="1000000000" step="0.01" inputmode="decimal" value="${Math.max(.01,Math.floor(Math.min(20,report.cash)))}" ${investLocked?'disabled':''}></label><button type="submit" class="secondary" ${investLocked?'disabled':''}>นำเงินลงทุน</button><button type="button" class="secondary" id="withdrawInvestment" ${investLocked||report.invested<=0?'disabled':''}>ถอนกลับมาใช้</button></form><p class="spending-warning" id="investmentError" role="status"></p><h3>ให้จัดการค่าใช้จ่ายทุกปี</h3><p class="spending-note">เปิดเฉพาะสิ่งที่ต้องการ ใช้รวมไม่เกิน 20% ของเงินพร้อมใช้และไม่เกิน 4,000 ทอง หากเงินไม่พอจะข้ามรายการนั้น</p><div class="recurring-options">${LifeSpending.catalog.filter(p=>p.recurring).map(p=>`<label><input type="checkbox" data-recurring="${p.id}" ${report.recurring.includes(p.id)?'checked':''} ${investLocked?'disabled':''}><span>${esc(p.name)}<small>${p.cost} ทอง</small></span></label>`).join('')}</div>${report.owned?`<details class="house-sale"><summary>ขายบ้านและกลับไปเช่า</summary><p>รับคืน ${number(report.homeValue)} ทอง ค่าครองชีพจะเพิ่มกลับตามที่พัก</p><button id="sellHouse" class="secondary" ${investLocked?'disabled':''}>ตรวจสอบการขายบ้าน →</button></details>`:''}${report.history.length?`<details class="spending-history"><summary>รายการรับจ่ายที่ผ่านมา</summary><ol>${report.history.map(h=>`<li><small>อายุ ${h.age} ปี</small><span>${esc(h.text)}</span></li>`).join('')}</ol></details>`:''}</section>`);
  document.querySelectorAll('[data-spend]').forEach(b=>b.onclick=()=>{if(LifeSpending.spend(state,b.dataset.spend))refresh('บันทึกการใช้เงินแล้ว')});
  document.querySelectorAll('[data-saving-strategy]').forEach(b=>b.onclick=()=>{if(LifeSpending.strategy(state,b.dataset.savingStrategy))refresh('เปลี่ยนแนวทางเงินลงทุนแล้ว')});
  document.querySelectorAll('[data-recurring]').forEach(b=>b.onchange=()=>{if(LifeSpending.recurring(state,b.dataset.recurring,b.checked)){save();toast(b.checked?'เปิดค่าใช้จ่ายประจำแล้ว':'ปิดค่าใช้จ่ายประจำแล้ว')}});
  function transfer(direction){const amount=Number($('#investmentAmount').value);if(LifeSpending.transfer(state,direction,amount))refresh(direction==='deposit'?'นำเงินเข้าบัญชีลงทุนแล้ว':'ถอนเงินกลับมาพร้อมใช้แล้ว');else $('#investmentError').textContent='ตรวจจำนวนเงินอีกครั้ง ยอดต้องมากกว่าศูนย์และไม่เกินเงินที่มี'}
  $('#investmentForm').onsubmit=e=>{e.preventDefault();transfer('deposit')};$('#withdrawInvestment').onclick=()=>transfer('withdraw');$('#openEconomyFromSpend').onclick=EpochUI.money;$('#spendShop').onclick=()=>LifeUI.shop();$('#spendPets').onclick=()=>LifeUI.companions();
  if($('#sellHouse'))$('#sellHouse').onclick=()=>{modal(`<section class="spending-dialog"><h2>ขายบ้านหลังนี้?</h2><p>รับคืน ${number(report.homeValue)} ทอง และกลับมาจ่ายค่าที่พักตามปกติ</p><div class="spending-links"><button id="keepHouse" class="secondary">เก็บบ้านไว้</button><button id="confirmSellHouse" class="secondary">ขายบ้าน</button></div></section>`);$('#keepHouse').onclick=open;$('#confirmSellHouse').onclick=()=>{if(LifeSpending.sellHouse(state))refresh('ขายบ้านแล้ว');else open()}};
 }
 function bind(){if($('#spendMoney'))$('#spendMoney').onclick=()=>RaceDrives.cashless(state)?BeliefUI.ways():open()}
 return {open,bind};
})();
